class Parcel:
    def __init__(self, kg):
        self.kg = kg


class Pallet(Parcel):
    def __init__(self, kg, boards):
        super().__init__(kg)
        self.boards = boards


pallet = Pallet(30, 4)
print(pallet.kg, pallet.boards)

class Crate:
    def __init__(self, items):
        self.items = items

    def __len__(self):
        return len(self.items)


crate = Crate(["a", "b"])
print(len(crate), bool(crate))

def flatten(items):
    flat = []
    for item in items:
        if isinstance(item, list):
            flat.extend(flatten(item))
        else:
            flat.append(item)
    return flat


print(flatten([1, [2, [3]], []]))
